"""Reconstruct the restored home map from A_000s; HUD-covered edges estimated.

This is a backdrop layout, not evidence that this level starts with these troops.
"""
from pathlib import Path
import json
import numpy as np
import cv2
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[2]
nodes=[]
def add(id,xy,s,owner='neutral',army=125,kind='normal',radius=None):
    p=[[int(v) for v in pair.split(',')] for pair in s.split()]
    n=dict(id=id,owner=owner,garrison=army,anchor=dict(x=xy[0],y=xy[1]),labelAnchor=dict(x=xy[0],y=xy[1]+13),polygons=[[dict(x=x,y=y) for x,y in p]],neighbors=[],kind=kind)
    if radius:n['coverageRadius']=radius
    nodes.append(n)
