# Home is a static backdrop. Neighbor graph is intentionally unused; keep it
# connected for reuse in a preview without asserting original attack routes.
for i,n in enumerate(nodes):
    if i:n['neighbors'].append(nodes[i-1]['id'])
    if i<len(nodes)-1:n['neighbors'].append(nodes[i+1]['id'])
native=dict(id='home-native',width=432,height=960,nodes=nodes)
(ROOT/'research/map-trace/home-native.json').write_text(json.dumps(native,indent=2),encoding='utf-8')
scale=1372/960;offx=(720-432*scale)/2
def trans(p):return dict(x=round(p['x']*scale+offx,3),y=round(p['y']*scale,3))
normalized=json.loads(json.dumps(native));normalized.update(id='home-reference',width=720,height=1372)
for n in normalized['nodes']:
    n['anchor']=trans(n['anchor']);n['labelAnchor']=trans(n['labelAnchor']);n['polygons']=[[trans(p) for p in poly] for poly in n['polygons']]
    if 'coverageRadius' in n:n['coverageRadius']=round(n['coverageRadius']*scale,3)
out="import type { GameMap } from '../sim/types';\n\n/** Home backdrop traced from restored A_000s. HUD-hidden regions estimated. Not a calibrated playable stage. */\nexport const homeMap: GameMap = "+json.dumps(normalized,indent=2)+';\n'
out+="export const homeMapAppearance = { background: '#d1d1d1', neutral: '#959897', blue: '#6dceec', red: '#f78d81', magenta: '#ee84b8', territoryBorder: '#d2d4d1' } as const;\n"
(ROOT/'src/maps/home.ts').write_text(out,encoding='utf-8')
pic=Image.open(ROOT/'media/analysis/A/A_000s.jpg').convert('RGBA');ol=Image.new('RGBA',pic.size);d=ImageDraw.Draw(ol)
for n in nodes:
    p=[(p['x'],p['y']) for p in n['polygons'][0]];d.line(p+[p[0]],fill=(220,0,0,255),width=1)
    x,y=n['anchor']['x'],n['anchor']['y'];d.ellipse((x-2,y-2,x+2,y+2),fill=(0,255,0,255))
Image.alpha_composite(pic,ol).convert('RGB').resize((864,1920)).save(ROOT/'research/map-trace/home-annotation-overlay.jpg',quality=95)
print('Wrote home backdrop',len(nodes),'regions')
